function createEvent(day, registrations) {
  return {
    id: `comicworld-339-${day}`,
    name: `코믹월드 339 일산 · ${day === 'sat' ? '토요일' : '일요일'}`,
    venue: '일산 킨텍스 제1전시장',
    date: day === 'sat' ? '2026년 11월 7일 (토)' : '2026년 11월 8일 (일)',
    hall: '공식 지도 좌측 부스 구역',
    coverage: '창작·전문·밀리터리 부스 구역',
    source: {
      map: 'https://comicw.net/map/339/',
      booths: 'https://comicw.net/map/339/',
      schedule: 'https://m.comicw.net/free/9486?ft=all',
      retrievedAt: '2026-11-23',
      scope: '공식 좌표가 있는 창작·전문·밀리터리 부스 구역. 좌표 없는 기업·기획 부스는 제외. 여러 칸을 쓰는 참가자는 자리별로 표시됩니다.',
      routing: '같은 회차 공식 배치도의 빈 통로와 일반 입구를 수동으로 재구성한 경로입니다. 현장 운영·통행 허용 여부는 반영하지 못합니다.',
      rights: '공식 홈페이지: Copyright © Comicw.co.kr All rights reserved. 원본 지도·부스컷 이미지는 포함하지 않습니다.'
    },
    map: {
      width: 330,
      height: 480,
      walkways,
      obstacles: slots.map(([code, , , x, y, width, height]) => ({ code, x: x - 70, y: y - 190, width, height })),
      zones: [
        { name: '창작 부스', x: 12, y: 10, width: 306, height: 110 },
        { name: '밀리터리 창작', x: 12, y: 130, width: 306, height: 48 },
        { name: '전문 부스', x: 31, y: 249, width: 287, height: 116 },
        { name: '밀리터리 전문', x: 122, y: 365, width: 196, height: 32 }
      ]
    },
    entrances: [{ id: 'south', name: '일반 입구', point: { x: 160, y: 460 }, access: { x: 160, y: 450 } }],
    categories,
    booths: slots.filter(([key]) => registrations[key]).map(([key, prefix, spec, x, y, width, height]) => {
      const [name, genre, originalBoothNumbers] = registrations[key];
      const access = prefix in verticalAccess
        ? { x: verticalAccess[prefix] - 70, y: y + height / 2 - 190 }
        : { x: x + width / 2 - 70, y: horizontalAccess[prefix] - 190 };
      return {
        id: `cw339-${day}-${key.toLowerCase()}`,
        code: `${prefix}_${key.slice(2)}`,
        name,
        category: categoryBySpec[spec],
        x: x - 70,
        y: y - 190,
        width,
        height,
        access,
        tags: genre.split(',').map(tag => tag.trim()).filter(tag => tag && tag !== '.' && tag !== '기타'),
        originalBoothNumbers
      };
    })
  };
}

export const realEvents = [createEvent('sat', saturday), createEvent('sun', sunday)];
